  "Needs input": "Girdi gerekiyor",
  "1. Material and producing source": "1. Malzeme ve üretim kaynağı",
  "Choose a CBAM precursor": "Bir CBAM öncül ürünü seçin",
  "Enter manually below": "Aşağıya elle girin",
  "Production route / technology": "Üretim güzergâhı / teknoloji",
  "Precursor name": "Öncül ürün adı",
  "Where was it produced?": "Nerede üretildi?",
  "Another installation": "Başka bir tesis",
  "Another process at my installation": "Tesisimdeki başka bir süreç",
  "Producer legal name": "Üreticinin yasal adı",
  "Producing installation": "Üretici tesis",
  "Registry installation ID, if assigned": "Sicil tesis kimliği, atanmışsa",
  "Country of production": "Üretim ülkesi",
  "Producer reporting period starts": "Üretici raporlama dönemi başlangıcı",
  "Producer reporting period ends": "Üretici raporlama dönemi bitişi",
