  "Official EU default": "Resmi AB varsayılanı",
  "Official EU default value (tCO₂e/t)": "Resmi AB varsayılan değeri (tCO₂e/t)",
  "Published value reference": "Yayımlanmış değer referansı",
  "Record the EU regulation/table, CN code, origin and applicable year.": "AB yönetmeliğini/tablosunu, KN kodunu, menşeini ve geçerli yılı kaydedin.",
  "The app has no official default-value table yet. Enter only the applicable published EU value; illustrative values are never inserted.": "Uygulamada henüz resmi varsayılan değer tablosu yok. Yalnızca geçerli yayımlanmış AB değerini girin; açıklayıcı değerler asla eklenmez.",
  "Open EU default-value regulation": "AB varsayılan değer yönetmeliğini aç",
  "Direct emissions (tCO₂e/t)": "Doğrudan emisyonlar (tCO₂e/t)",
  "Indirect emissions (tCO₂e/t), if applicable": "Dolaylı emisyonlar (tCO₂e/t), varsa",
  "Upload the producer's independent verification report. Then enter the report details below so its coverage can be checked.": "Üreticinin bağımsız doğrulama raporunu yükleyin. Ardından kapsamının kontrol edilebilmesi için aşağıya rapor ayrıntılarını girin.",
  "Producer verification report": "Üretici doğrulama raporu",
  "A document is attached. Its contents and accreditation still require human review.": "Bir belge eklendi. İçeriği ve akreditasyonu hâlâ insan incelemesi gerektiriyor.",
  "Report covers from": "Rapor şu tarihten itibaren kapsar",
  "Report covers until": "Rapor şu tarihe kadar kapsar",
  "Select country": "Ülke seçin",
  "Passing these field checks does not replace an independent review of the report and accreditation.": "Bu alan kontrollerini geçmek, raporun ve akreditasyonun bağımsız incelemesinin yerini tutmaz.",
  "3. Tonnes actually used": "3. Gerçekten kullanılan tonlar",
  "Enter material consumed by your process, including losses. A delivery receipt is not the same as use.": "Sürecinizin tükettiği malzemeyi kayıplar dahil girin. Teslimat makbuzu kullanımla aynı değildir.",
  "Used this year": "Bu yıl kullanılan",
  "{process} used in {month} (t)": "{month} ayında {process} süreci kullanımı (t)",
  "Save source": "Kaynağı kaydet",
  "Unsaved changes": "Kaydedilmemiş değişiklikler",
  "Confirm remove source": "Kaynağın kaldırılmasını onayla",
  "Remove source": "Kaynağı kaldır",
  "Usage is split by production process. Edit it on the Precursor sources tab.": "Kullanım üretim sürecine göre bölünmüştür. Öncül ürün kaynakları sekmesinde düzenleyin.",
  "{source}: exact 8-digit precursor CN code": "{source}: tam 8 haneli öncül ürün KN kodu",
  "{source}: producer installation and country": "{source}: üretici tesis ve ülke",
  " — enter the applicable official EU default and its source; illustrative comparison values are not used here.": " — geçerli resmi AB varsayılanını ve kaynağını girin; açıklayıcı karşılaştırma değerleri burada kullanılmaz.",
  "The report is attached. Enter its values manually; automatic suggestions require a text PDF.": "Rapor eklendi. Değerlerini elle girin; otomatik öneriler metin içeren bir PDF gerektirir.",
  "Check each value from the PDF before using it.": "Kullanmadan önce PDF’teki her değeri kontrol edin.",
  "No unambiguous precursor values found. The report is attached; enter its values manually.": "Net bir öncül ürün değeri bulunamadı. Rapor eklendi; değerlerini elle girin.",
  "Could not read text from this PDF. The report is attached; enter its values manually.": "Bu PDF’ten metin okunamadı. Rapor eklendi; değerlerini elle girin.",
  "specificEmbeddedDirectTco2PerT": "specificEmbeddedDirectTco2PerT",
  "specificEmbeddedIndirectTco2PerT": "specificEmbeddedIndirectTco2PerT",
  "cnCode": "cnCode",
  "reportingPeriodStart": "reportingPeriodStart",
  "reportingPeriodEnd": "reportingPeriodEnd",
  "Use value": "Değeri kullan",
  "I checked this number against the official EU table for this CN code, origin and year.": "Bu sayıyı, bu KN kodu, menşei ve yıl için resmi AB tablosuna karşı kontrol ettim.",
  "Clear this process's monthly quantities before removing it.": "Bu süreci kaldırmadan önce aylık miktarlarını temizleyin.",
  "Pending value": "Bekleyen değer",
  "This claimed actual figure cannot be used yet. Complete the verification report details or explicitly choose an official EU default:": "Bu iddia edilen gerçek değer henüz kullanılamaz. Doğrulama raporu ayrıntılarını tamamlayın veya açıkça bir resmi AB varsayılanı seçin:",
  "Upload the producer report or select an EU default": "Üretici raporunu yükleyin veya bir AB varsayılanı seçin",
  "Choose the emissions data source, then upload the producer report if using actual values": "Emisyon veri kaynağını seçin; gerçek değerler kullanılıyorsa üretici raporunu yükleyin",
  "Upload producer report": "Üretici raporunu yükle",
  "Upload producer verification report": "Üretici doğrulama raporunu yükle",
  "Choose where this precursor's emissions value comes from.": "Bu öncül ürünün emisyon değerinin nereden geldiğini seçin.",
  "Emissions data source": "Emisyon veri kaynağı",
  "Producer's verified report": "Üreticinin doğrulanmış raporu",
  "Use the producer's verified figures. Upload the file below.": "Üreticinin doğrulanmış rakamlarını kullanın. Dosyayı aşağıya yükleyin.",
  "Official EU default value": "Resmi AB varsayılan değeri",
  "Use the published EU value for this precursor and country.": "Bu öncül ürün ve ülke için yayımlanmış AB değerini kullanın.",
  "Use official EU default": "Resmi AB varsayılanını kullan",
  "EU schedule value for this CN code and production country": "Bu KN kodu ve üretim ülkesi için AB çizelge değeri",
  "The EU schedule uses its Other countries and territories row for this origin.": "AB çizelgesi bu menşe için “Diğer ülkeler ve bölgeler” satırını kullanır.",
  "EU value selected": "AB değeri seçildi",
  "Select this EU value": "Bu AB değerini seç",
  "The number comes from the Commission's corrected August 2026 schedule. Check the legal text before filing.": "Bu sayı, Komisyon’un düzeltilmiş Ağustos 2026 çizelgesinden alınmıştır. Dosyalamadan önce yasal metni kontrol edin.",
  "Regulation": "Yönetmelik",
  "Commission workbook": "Komisyon çalışma kitabı",
  "Choose the exact 8-digit CN code and production country to find a published EU default. If no unique row exists, obtain the producer's report.": "Yayımlanmış bir AB varsayılanı bulmak için tam 8 haneli KN kodunu ve üretim ülkesini seçin. Tekil bir satır yoksa üreticinin raporunu temin edin.",
  "An EU default schedule for this reporting year is not loaded. Obtain the producer's report.": "Bu raporlama yılı için AB varsayılan çizelgesi yüklenmedi. Üreticinin raporunu temin edin.",
  "The emissions figure must come from the producer's report. Review the extracted figure below; you cannot type your own figure here.": "Emisyon değeri üreticinin raporundan gelmelidir. Aşağıdaki çıkarılmış değeri inceleyin; burada kendi değerinizi yazamazsınız.",
  "Total emissions (tCO₂e/t)": "Toplam emisyonlar (tCO₂e/t)",
  "Waiting for report": "Rapor bekleniyor",
  "Production country unknown": "Üretim ülkesi bilinmiyor",
  "The report is attached, but figures can only be read from a text PDF. Upload a text PDF or select the EU default.": "Rapor eklendi, ancak rakamlar yalnızca metin içeren bir PDF’ten okunabilir. Metin içeren bir PDF yükleyin veya AB varsayılanını seçin.",
  "Review each figure extracted from the producer's PDF before using it.": "Kullanmadan önce üreticinin PDF’inden çıkarılan her rakamı inceleyin.",
  "No clear emissions figure was found. Ask the producer for a readable report or select the EU default.": "Net bir emisyon rakamı bulunamadı. Üreticiden okunabilir bir rapor isteyin veya AB varsayılanını seçin.",
