  "Total": "Toplam",
  "Submitted {date} by {name}.": "{name} tarafından {date} tarihinde gönderildi.",
  "{n} error — this month cannot be submitted": "{n} hata — bu ay gönderilemez",
  "{n} errors — this month cannot be submitted": "{n} hata — bu ay gönderilemez",
  "{n} thing worth a look — none of them block submission.": "Bakılmaya değer {n} konu — hiçbiri göndermeyi engellemez.",
  "{n} things worth a look — none of them block submission.": "Bakılmaya değer {n} konu — hiçbiri göndermeyi engellemez.",
  "The version they submitted goes back unchanged.": "Gönderdikleri sürüm değişmeden geri döner.",
  "You have not edited it.": "Bunu düzenlemediniz.",
  "Nothing has been submitted for {month} yet, so there is nobody to send it back to. Send the month’s link from the Monthly data tab first.": "{month} için henüz bir şey gönderilmedi, bu yüzden geri gönderilecek kimse yok. Önce Aylık veriler sekmesinden ayın bağlantısını gönderin.",
  "With {name}.": "{name} ile.",
  "Confirmed by {name}.": "{name} tarafından onaylandı.",
  "Required — Certrace will not substitute a standard value.": "Zorunlu — Certrace standart bir değeri yerine koymaz.",
  "For reference, this fuel is typically {range}.": "Referans olarak, bu yakıt genellikle {range} aralığındadır.",
  "For reference, this fuel is EU standard value {range}.": "Referans olarak, bu yakıtın AB standart değeri {range}.",
  "{ef} tCO₂/GJ{ncv} — EU standard value, IPCC 2006 GL ({cite}). Locked.": "{ef} tCO₂/GJ{ncv} — AB standart değeri, IPCC 2006 GL ({cite}). Kilitli.",
  "Smart upload · {file}": "Akıllı yükleme · {file}",
  "oxide, output-based": "oksit, çıktıya dayalı",
  "litre": "litre",
  "{fuelType} — emission factor out of band": "{fuelType} — emisyon faktörü kabul aralığının dışında",
  "{ef} tCO₂/GJ is outside the {min}–{max} range every fossil fuel sits in.": "{ef} tCO₂/GJ, fosil yakıtların tamamının içinde yer aldığı {min}–{max} aralığının dışında.",
  "The usual cause is a factor stated per m³ or per litre rather than per gigajoule, which is roughly 25× out.": "Olağan neden, faktörün gigajul başına değil m³ veya litre başına belirtilmesidir; bu da yaklaşık 25× sapma demektir.",
  "{fuelType} — calorific value looks like the wrong unit": "{fuelType} — ısıl değer yanlış birim gibi görünüyor",
  "Check whether the figure on the spec sheet is in kJ or in MJ.": "Teknik föydeki değerin kJ mi MJ mi olduğunu kontrol edin.",
  "{grid} tCO₂/MWh is above the dirtiest grid on record.": "{grid} tCO₂/MWh, kayıtlardaki en kirli şebekenin de üzerinde.",
  "Thailand's published factor is 0.4999.": "Tayland'ın yayımladığı faktör 0,4999.",
  "A factor given in kgCO₂/kWh is the same number 1000× out.": "kgCO₂/kWh cinsinden verilen bir faktör, aynı sayının 1000× sapmış halidir.",
  "This month works out at {toFixed} tCO₂e per tonne.": "Bu ay ton başına {toFixed} tCO₂e çıkıyor.",
  "CBAM iron & steel and aluminium installations report between {min} and {max}.": "CBAM demir-çelik ve alüminyum tesisleri {min} ile {max} arasında bildirir.",
  "Check the production tonnage and the fuel quantities are both for this month, and both in the units the form asks for.": "Üretim tonajının ve yakıt miktarlarının her ikisinin de bu aya ait olduğunu ve formun istediği birimlerde olduğunu kontrol edin.",
  "{toFixed} MWh per tonne.": "Ton başına {toFixed} MWh.",
  "Even a primary aluminium smelter is around 15.": "Birincil alüminyum eritmesi bile yaklaşık 15 civarındadır.",
  "Check the meter reading is in MWh rather than kWh.": "Sayaç okumasının kWh değil MWh cinsinden olduğunu kontrol edin.",
  "Fuel is recorded but production is zero.": "Yakıt kaydedilmiş ama üretim sıfır.",
  "If the plant ran, the tonnage is missing; if it was idle, the fuel belongs outside the boundary and the methodology should say so.": "Tesis çalıştıysa tonaj eksik demektir; boştaysa yakıt sınır dışında kalır ve metodoloji bunu belirtmelidir.",
  "{toFixed} t against an average of {toFixed} t across the {length} months already reported.": "{toFixed} t; bildirilmiş {length} ayın ortalaması {toFixed} t.",
  "A shutdown, a campaign or a big order all explain it — but so does a decimal point, so it is worth one look.": "Bir duruş, bir kampanya veya büyük bir sipariş bunu açıklayabilir; ama ondalık nokta hatası da olabilir, bu yüzden bir kez bakmaya değer.",
  "{fuelType} has not appeared in any other month": "{fuelType} başka hiçbir ayda görünmüyor",
  "A new fuel is fine if the plant genuinely switched or trialled one.": "Tesis gerçekten yakıt değiştirdiyse veya denediyse yeni bir yakıt sorun değildir.",
  "If it is the same fuel under a different name, pick the name the other months use so the year can be summed.": "Aynı yakıt farklı bir adla geçiyorsa, yıl toplanabilsin diye diğer ayların kullandığı adı seçin.",
  "A figure with no document behind it is the first thing a verifier removes.": "Arkasında belgesi olmayan bir rakam, doğrulayıcının ilk çıkaracağı şeydir.",
  "Attach the utility invoice, the fuel delivery notes and the production log.": "Fatura, yakıt teslim irsaliyelerini ve üretim kaydını ekleyin.",
  "The form will not submit until these are answered.": "Bunlar yanıtlanmadan form gönderilmez.",
  "Each one is a figure something downstream divides by or multiplies with.": "Her biri, sonraki bir hesapta bölünen veya çarpılan bir değerdir.",
  "Present, but outside what the quantity can physically be or what the sector reports.": "Mevcut, ama miktarın fiziksel olarak olabileceği veya sektörün bildirdiği değerlerin dışında.",
  "Usually a unit.": "Genellikle bir birim hatasıdır.",
  "Plausible on its own, unusual next to the rest of the year.": "Tek başına makul, ama yılın geri kalanına göre olağandışı.",
  "Worth one look, then carry on.": "Bir kez bakmaya değer, sonra devam edin.",
  "{month} submitted": "{month} gönderildi",
  "{fuels} reverted to the EU standard value": "{fuels} AB standart değerine geri döndü",
  "For {product} produced at {installation} — everything below is about this one month.": "{installation} tesisinde üretilen {product} için — aşağıdaki her şey bu tek aya ilişkindir.",
  "{month} is submitted and read-only. Ask the exporter to reopen it if something was wrong.": "{month} gönderildi ve salt okunur. Bir yanlışlık varsa ihracatçıdan yeniden açmasını isteyin.",
  "Submit {month}": "{month} ayını gönder",
