  "Every conversation you have with Cera is kept here, so you can pick it up again.": "Cera ile yaptığınız her sohbet burada saklanır, böylece kaldığınız yerden devam edebilirsiniz.",
  "Exit full screen": "Tam ekrandan çık",
  "What can Cera help you with?": "Cera size nasıl yardımcı olabilir?",
