  "No file to hand? Try an example": "Elinizde dosya yok mu? Bir örnek deneyin",
  "Download one, then drop it above. Each holds only a few readings — enough to see how it works.": "Birini indirin, sonra yukarıya bırakın. Her biri yalnızca birkaç okuma içerir — nasıl çalıştığını görmek için yeterli.",
  "Choose one": "Birini seçin",
  "You changed this — the file says": "Bunu siz değiştirdiniz — dosyada yazan:",
  "Undo": "Geri al",
  "From the file": "Dosyadan",
  "This is what I found. Check each figure against your file and change anything that is not right — nothing goes into the form until you confirm.": "Bulduklarım bunlar. Her rakamı dosyanızla karşılaştırın ve doğru olmayanı değiştirin — onaylayana kadar hiçbir şey forma girmez.",
  "Include": "Dahil et",
  "Discarded — nothing was saved": "Atıldı — hiçbir şey kaydedilmedi",
