  "Confirm and fill in": "Onayla ve doldur",
  "Coming up": "Yakında",
  "Already in force": "Zaten yürürlükte",
  "Flag new rule changes on my button": "Yeni kural değişikliklerini düğmemde işaretle",
  "Flag new rule changes": "Yeni kural değişikliklerini işaretle",
