  "Show all {n}": "Tümünü göster ({n})",
  "That is not a number.": "Bu bir sayı değil.",
  "It cannot be negative.": "Negatif olamaz.",
  "It has to be more than 0.": "0'dan büyük olmalı.",
  "Choose one.": "Birini seçin.",
  "the readings are in kWh": "okumalar kWh cinsinden",
