  "Cell-days in the month": "Ay içindeki hücre-gün",
  "Cells in operation × days — so the minutes can be traced to the cells.": "Çalışan hücreler × gün — böylece dakikalar hücrelere izlenebilir.",
  "Cell-days": "Hücre-gün",
