  "Average minutes per cell-day:": "Hücre-gün başına ortalama dakika:",
  "My cells are not all one type, or the lines run differently": "Hücrelerim hepsi aynı tipte değil veya hatlar farklı çalışıyor",
  "What the steel is made of": "Çelik neyden yapılmış",
  "Product composition": "Ürün bileşimi",
  "The alloying elements of what was made this month, from the mill test certificates, weighted by the heats cast.": "Bu ay üretilenlerin alaşım elementleri; malzeme test sertifikalarından, döküm ısılarıyla ağırlıklandırılmış.",
  "The report states Mn, Cr, Ni and the other alloying elements for the year: the months' figures, weighted by what was made in each. Leave a month empty if it was ordinary carbon steel with only trace elements.": "Rapor, yıl için Mn, Cr, Ni ve diğer alaşım elementlerini belirtir: ayların rakamları, her birinde üretilen miktarla ağırlıklandırılmış. Ay yalnızca eser elementler içeren sıradan karbonlu çelikse boş bırakın.",
  "Optional. Weighted by tonnes made across the year in the report.": "İsteğe bağlı. Raporda yıl boyunca üretilen tonla ağırlıklandırılır.",
  "Manganese.": "Mangan.",
  "Chromium.": "Krom.",
  "Nickel.": "Nikel.",
  "All other alloying elements together.": "Diğer tüm alaşım elementleri birlikte.",
  "Where the figures come from": "Rakamların kaynağı",
  "So a verifier knows which certificates to ask for.": "Doğrulayıcının hangi sertifikaları isteyeceğini bilmesi için.",
  "The alloying elements add up to more than 100 %.": "Alaşım elementlerinin toplamı %100'ü aşıyor.",
  "Ask about CBAM or Certrace": "CBAM veya Certrace hakkında sorun",
  "Text or CSV · one at a time · or press to choose": "Metin veya CSV · tek tek · veya seçmek için basın",
  "What goes to the verifier": "Doğrulayıcıya giden",
  "Everything this installation hands over for {year}, in one package: the reports you write, and the papers that travel with them.": "Bu tesisin {year} için tek pakette teslim ettiği her şey: yazdığınız raporlar ve bunlara eşlik eden belgeler.",
  "Attachments": "Ekler",
  "Not reports you write. Each is an index of papers that travel in the package, beside the reports — and neither holds the package back.": "Yazdığınız raporlar değildir. Her biri, raporların yanında pakette giden belgelerin bir dizinidir — ve hiçbiri paketi geciktirmez.",
  "Monitoring plan, operator's emissions report, summary report": "İzleme planı, işletmecinin emisyon raporu, özet rapor",
  "Addendum": "Ek",
  "Electricity goes to the EU — one per declarant": "Elektrik AB'ye gider — beyan sahibi başına bir",
  "Not needed — no electricity goes to the EU": "Gerekmiyor — AB'ye elektrik gitmiyor",
  "Precursor verification reports, supporting evidence": "Öncül ürün doğrulama raporları, destekleyici kanıtlar",
  "Contains": "İçerir",
  "to get": "alınacak",
  "Still to get": "Hâlâ alınacak",
  "Each installation you report on hands over one package a year: the monitoring plan, the operator's emissions report and the summary report — a declarant addendum where electricity goes to the EU — and, beside them, the verification reports of your precursors' installations and the supporting evidence. It covers every product the site makes, and downloads once all of it is complete.": "Raporladığınız her tesis yılda bir paket teslim eder: izleme planı, işletmecinin emisyon raporu ve özet rapor — elektriğin AB'ye gittiği yerde beyan sahibi eki — ve bunların yanında öncül ürünlerinizin tesislerinin doğrulama raporları ve destekleyici kanıtlar. Tesisin ürettiği her ürünü kapsar ve tamamı tamamlandığında indirilir.",
  "documents": "belge",
  "The product report is not complete": "Ürün raporu tamamlanmadı",
  "{n} of {total} product reports are not complete": "{total} ürün raporundan {n} tanesi tamamlanmadı",
  "{n} item(s) of the installation's information are still missing": "Tesis bilgilerinden {n} öğe hâlâ eksik",
  "{n} item(s) to do": "{n} öğe yapılacak",
  "Monitoring plan": "İzleme planı",
  "Operator's emissions report": "İşletmecinin emisyon raporu",
  "Operator's summary emissions report": "İşletmecinin özet emisyon raporu",
  "Declarant-specific addendum": "Beyan sahibine özel ek",
  "Verification reports of precursor installations": "Öncül ürün tesislerinin doğrulama raporları",
  "Supporting evidence and records": "Destekleyici kanıtlar ve kayıtlar",
  "What the installation monitors and how, element by element as the template lists them. The verifier reads it before the year is verified.": "Tesisin neyi nasıl izlediği, şablonun listelediği gibi öğe öğe. Doğrulayıcı yıl doğrulanmadan önce bunu okur.",
  "The full report the verifier verifies. It is in English (Article 10(4)).": "Doğrulayıcının doğruladığı tam rapor. İngilizcedir (Madde 10(4)).",
  "The shortened report passed on to authorised CBAM declarants (Article 8).": "Yetkili CBAM beyan sahiplerine iletilen kısaltılmış rapor (Madde 8).",
  "One per authorised declarant, only for electricity imported into the EU.": "Yetkili beyan sahibi başına bir, yalnızca AB'ye ithal edilen elektrik için.",
  "This installation does not export electricity to the EU, so no addendum is needed.": "Bu tesis AB'ye elektrik ihraç etmediği için ek gerekmez.",
  "The verification reports of the installations that made your precursors on actual values. The reports themselves are in the package, beside this index.": "Öncül ürünlerinizi gerçek değerlerle üreten tesislerin doğrulama raporları. Raporların kendisi, bu dizinin yanında pakettedir.",
  "Every document behind a figure, and the figure it supports, so the verifier can sample a month and find its paper. The documents themselves are in the package, beside this index.": "Bir rakamın arkasındaki her belge ve desteklediği rakam; doğrulayıcının bir ayı örnekleyip kağıdını bulabilmesi için. Belgelerin kendisi, bu dizinin yanında pakettedir.",
  "Operator and installation": "İşletmeci ve tesis",
  "1 · Operator and installation": "1 · İşletmeci ve tesis",
  "1–2 · Operator and installation": "1–2 · İşletmeci ve tesis",
