  "To do": "Yapılacak",
  "Cera reads a file and fills the form. You check every figure before it is saved — Cera can make mistakes.": "Cera bir dosyayı okur ve formu doldurur. Kaydedilmeden önce her rakamı siz kontrol edersiniz — Cera hata yapabilir.",
  "Drop a file on the document it belongs to, or click it to choose one.": "Bir dosyayı ait olduğu belgenin üzerine bırakın veya seçmek için tıklayın.",
  "Smart upload": "Akıllı yükleme",
  "Drop any documents here": "Belgeleri buraya bırakın",
  "Drop your plant's documents here": "Tesisinizin belgelerini buraya bırakın",
  "Bills, invoices, meter logs, ERP exports, certificates — as many as you like. Certrace works out what each one is, which month it covers and where it belongs. Nothing is filed until you confirm.": "Faturalar, fatura belgeleri, sayaç kayıtları, ERP dışa aktarımları, sertifikalar — istediğiniz kadar. Certrace her birinin ne olduğunu, hangi ayı kapsadığını ve nereye ait olduğunu belirler. Onaylayana kadar hiçbir şey dosyalanmaz.",
