  "AI can make mistakes — check each value against its document. Typing over a value makes it yours.": "YZ hata yapabilir — her değeri belgesiyle karşılaştırın. Bir değerin üzerine yazmak onu sizin yapar.",
  "AI can make mistakes, even on rows marked ready. Check each value against its document before you confirm.": "YZ hata yapabilir, hazır olarak işaretlenen satırlarda bile. Onaylamadan önce her değeri belgesiyle karşılaştırın.",
