  "Add documents and let Certrace fill the form": "Belgeleri ekleyin ve Certrace formu doldursun",
  "Drop this month's bills, fuel invoices and ERP exports. AI reads each one, files it and fills the matching figures. You check everything before it is saved — AI can make mistakes.": "Bu ayın faturalarını, yakıt faturalarını ve ERP dışa aktarımlarını bırakın. YZ her birini okur, dosyalar ve eşleşen rakamları doldurur. Kaydedilmeden önce her şeyi siz kontrol edersiniz — YZ hata yapabilir.",
