  "Every regulation, market and period you're filing for. A declaration is the unit of compliance — scope it once, the platform runs the rest.": "Dosyaladığınız her düzenleme, pazar ve dönem. Beyan uyumluluğun birimidir — kapsamını bir kez belirleyin, platform gerisini yürütür.",
