  "{name} — {suppliers} suppliers · {products} products · {lots} lots queued.": "{name} — {suppliers} tedarikçi · {products} ürün · {lots} parti sırada.",
  "Compliance regulation": "Uyumluluk düzenlemesi",
  "Which regime are you reporting for? Certrace launched on CBAM — the obligation that bites first for exporters into the EU. The rest run on the same engine and switch on as their data models are verified.": "Hangi rejim için raporluyorsunuz? Certrace CBAM ile başladı — AB'ye ihracat yapan firmalar için ilk bağlayıcı yükümlülük. Diğerleri aynı motorda çalışır ve veri modelleri doğrulandıkça açılır.",
  "Export route": "İhracat rotası",
  "Where do you export from, and into which market? {reg} applies to goods entering the EU — your origin sets the emission-factor library Certrace calculates with.": "Nereden ihracat yapıyorsunuz ve hangi pazara? {reg} AB'ye giren mallara uygulanır — menşeiniz, Certrace'in hesapladığı emisyon faktörü kütüphanesini belirler.",
