  "Planned · rubber, palm oil, electronics.": "Planlandı · kauçuk, palm yağı, elektronik.",
  "EU CBAM Registry · via importer / declarant": "AB CBAM Sicili · ithalatçı / beyan sahibi aracılığıyla",
  "What is this declaration for?": "Bu beyan ne için?",
  "Choose one — the official CBAM filing, or a specific buyer's data request. Each has its own qualification checklist, so keep the two separate.": "Birini seçin — resmi CBAM dosyalaması ya da belirli bir alıcının veri talebi. Her birinin kendi nitelik kontrol listesi vardır, bu yüzden ikisini ayrı tutun.",
  "CBAM Compliance": "CBAM Uyumluluğu",
  "Automatically prepares supplier data collection based on CBAM requirements. Fields, CN codes and templates are generated for you.": "CBAM gerekliliklerine göre tedarikçi veri toplamasını otomatik hazırlar. Alanlar, KN kodları ve şablonlar sizin için oluşturulur.",
  "Buyer Request": "Alıcı Talebi",
  "Create a custom supplier request for buyer-specific information — documents, certificates and questionnaires on top of the carbon data.": "Alıcıya özel bilgiler için özel bir tedarikçi talebi oluşturun — karbon verisinin yanında belgeler, sertifikalar ve anketler.",
  "e.g. CBAM 2026 Annual": "ör. CBAM 2026 Yıllık",
  "e.g. ABC Buyer Carbon Data Request": "ör. ABC Alıcı Karbon Veri Talebi",
  "Request name": "Talep adı",
  "Shown to suppliers and on every reminder. Make it recognisable.": "Tedarikçilere ve her hatırlatmada gösterilir. Kolay tanınabilir yapın.",
  "Request description (optional)": "Talep açıklaması (isteğe bağlı)",
  "Context for your suppliers — what this is for.": "Tedarikçileriniz için bağlam — bu ne için.",
  "e.g. Annual CBAM carbon data for our EU steel exports. Please report at installation level.": "ör. AB'ye çelik ihracatımız için yıllık CBAM karbon verisi. Lütfen tesis düzeyinde raporlayın.",
  "EU buyer / importer (required)": "AB alıcısı / ithalatçı (zorunlu)",
  "EU buyer / importer": "AB alıcısı / ithalatçı",
  "Who imports these goods into the EU? Their Authorised CBAM Declarant files the declaration — Certrace addresses the Communication Template and the O3CI share to them.": "Bu malları AB'ye kim ithal ediyor? Yetkili CBAM beyan sahipleri beyanı dosyalar — Certrace İletişim Şablonunu ve O3CI paylaşımını onlara iletir.",
  "The buyer this data request is for.": "Bu veri talebinin sahibi olan alıcı.",
  "Buyer legal name": "Alıcının yasal adı",
  "EORI number": "EORI numarası",
  "Format: 2-letter country + 6–15 characters, e.g. DE551234567890": "Biçim: 2 harfli ülke kodu + 6–15 karakter, ör. DE551234567890",
  "The declarant's Registry identifier.": "Beyan sahibinin Sicil tanımlayıcısı.",
  "Contact email": "İletişim e-postası",
  "Enter a valid email address.": "Geçerli bir e-posta adresi girin.",
  "Where the Communication Template is sent.": "İletişim Şablonunun gönderileceği adres.",
  "Buyer requests can run on any cadence. Pick the rhythm that matches how this buyer wants the data.": "Alıcı talepleri herhangi bir sıklıkta çalışabilir. Bu alıcının verileri nasıl istediğine uyan ritmi seçin.",
  "Official CBAM declarations are annual — but you can collect supplier data quarterly if that fits your cycle.": "Resmi CBAM beyanları yıllıktır — ancak döneminize uyuyorsa tedarikçi verisini çeyreklik de toplayabilirsiniz.",
  "Quarterly": "Üç aylık",
  "Semi-annual": "Altı aylık",
  "Official CBAM cadence — recommended. Suppliers can report at year-end.": "Resmi CBAM sıklığı — önerilir. Tedarikçiler yıl sonunda raporlayabilir.",
  "Collect supplier data each quarter (one quarter at a time).": "Her çeyrek tedarikçi verisini toplayın (her seferinde bir çeyrek).",
  "Once per calendar year.": "Takvim yılı başına bir kez.",
