  "Search the CBAM goods catalogue by product name, CN code or HS code. Pick everything in scope — reorder to match how you brief suppliers.": "CBAM mal kataloğunda ürün adına, KN koduna veya HS koduna göre arayın. Kapsamdaki her şeyi seçin — tedarikçilerinize nasıl brifing verdiğinize uyacak şekilde sıralayın.",
