  "No products match “{query}”.": "“{query}” ile eşleşen ürün yok.",
  "In scope": "Kapsamda",
  "Nothing selected yet. Tick products on the left to add them.": "Henüz bir şey seçilmedi. Eklemek için soldaki ürünleri işaretleyin.",
  "Move up": "Yukarı taşı",
