  "Classification & report fields": "Sınıflandırma ve rapor alanları",
  "Certrace classified each product automatically — category, CN / HS codes and the CBAM template come from the catalogue and can't be edited. The checklist below reflects the data points that actually apply to the goods you selected.": "Certrace her ürünü otomatik olarak sınıflandırdı — kategori, KN / HS kodları ve CBAM şablonu katalogdan gelir ve düzenlenemez. Aşağıdaki kontrol listesi, seçtiğiniz mallara gerçekten uygulanan veri noktalarını yansıtır.",
  "CBAM report fields": "CBAM rapor alanları",
  "Carbon data to request": "İstenecek karbon verisi",
  "{included} of {total} included": "{total} içinden {included} dahil",
  "These are the data points CBAM requires for the goods you selected. Required fields are locked on; the rest are recommended and on by default — keep or drop them to match how you collect data.": "Bunlar seçtiğiniz mallar için CBAM'in gerektirdiği veri noktalarıdır. Zorunlu alanlar açık kilitlidir; diğerleri önerilir ve varsayılan olarak açıktır — veri toplama şeklinize uyması için tutun ya da kaldırın.",
  "Choose the carbon-data fields this buyer needs. Recommended fields are pre-selected because buyers commonly ask for them — adjust freely, keeping at least one.": "Bu alıcının ihtiyaç duyduğu karbon verisi alanlarını seçin. Önerilen alanlar alıcıların sık istediği alanlar olduğu için önceden seçilidir — en az birini tutarak serbestçe düzenleyin.",
  "Select {field}": "{field} alanını seç",
