  "Steel: e.g. BF-BOF, EAF, DRI-EAF · Aluminium: e.g. electrolysis (Hall-Héroult), remelt, extrusion": "Çelik: ör. BF-BOF, EAF, DRI-EAF · Alüminyum: ör. elektroliz (Hall-Héroult), yeniden eritme, ekstrüzyon",
  "Quantity covered by this request (net mass, t)": "Bu talebin kapsadığı miktar (net kütle, t)",
