  "Your {plan} plan keeps one reporting year open at a time.": "{plan} planınız her seferinde bir raporlama yılını açık tutar.",
  "Your {plan} plan includes a single team seat, and it is taken.": "{plan} planınız tek bir ekip koltuğu içerir ve dolu.",
  "Talk to sales to raise it — suppliers stay free and unlimited either way.": "Artırmak için satışla konuşun — tedarikçiler her durumda ücretsiz ve sınırsız kalır.",
  "Compare plans": "Planları karşılaştır",
  "No seats left on your plan.": "Planınızda kalan koltuk yok.",
  "no cap on your plan": "planınızda üst sınır yok",
  "see what each tier includes →": "her kademenin neleri içerdiğini görün →",
  "Every seat on your plan is taken. Remove someone to free one, or talk to sales — suppliers still cost nothing and never take a seat.": "Planınızdaki her koltuk dolu. Bir koltuğu boşaltmak için birini kaldırın ya da satışla konuşun — tedarikçiler yine ücretsizdir ve asla koltuk kullanmaz.",
  "free and unlimited on every plan": "her planda ücretsiz ve sınırsız",
  "Suppliers are free and unlimited on every tier, at any chain depth, and never take a seat.": "Tedarikçiler her kademede, zincirin herhangi bir derinliğinde ücretsiz ve sınırsızdır; asla koltuk kullanmaz.",
  "Every site you operate yourself. Register them here once and their monthly data lands in your inbox instead of going out to a supplier. Your plan covers one site.": "Kendiniz işlettiğiniz her saha. Bunları burada bir kez kaydedin; aylık verileri bir tedarikçiye gitmek yerine gelen kutunuza düşer. Planınız bir sahayı kapsar.",
  "Every site you operate yourself. Register them here once and their monthly data lands in your inbox instead of going out to a supplier. Your plan covers {cap} sites.": "Kendiniz işlettiğiniz her saha. Bunları burada bir kez kaydedin; aylık verileri bir tedarikçiye gitmek yerine gelen kutunuza düşer. Planınız {cap} sahayı kapsar.",
  "CN {code} would be a new code on your plan.": "CN {code} planınızda yeni bir kod olur.",
  "Codes you already report — and any number of sites or years reporting them — cost nothing more.": "Zaten raporladığınız kodlar — ve bunları raporlayan herhangi bir sayıda saha veya yıl — ek bir maliyet getirmez.",
  "{year} would be a new reporting year. Archiving a finished year frees its slot — nothing behind it is deleted.": "{year} yeni bir raporlama yılı olur. Tamamlanmış bir yılı arşivlemek yuvasını boşaltır — arkasındaki hiçbir şey silinmez.",
