  "Every declaration in one place: what the certificates cost, which suppliers and goods carry the emissions, and whose data has aged past the point you should still be filing it.": "Tüm beyanlar tek bir yerde: sertifikaların maliyeti, emisyonları hangi tedarikçilerin ve malların taşıdığı ve hangi verinin hâlâ dosyalamanız gerektiği noktayı geçecek kadar eskidiği.",
