  "Once suppliers submit and you approve their figures, the cost, the hotspots and the benchmark all appear here — across every declaration at once.": "Tedarikçiler gönderip rakamlarını onayladığınızda, maliyet, sıcak noktalar ve kıyas burada — tüm beyanlar genelinde birlikte — görünür.",
