  "Priced at": "Fiyat",
  "{amount} on every tonne you ship. An estimate for planning: the declarant buys at the published auction average for the week of import.": "Sevk ettiğiniz her ton için {amount}. Planlama için bir tahmin: beyan sahibi ithalat haftasının yayımlanmış ortalama ihale fiyatından alım yapar.",
  "Certificate price in EUR per tonne CO2e": "Ton CO2e başına EUR cinsinden sertifika fiyatı",
  "Carbon hotspots": "Karbon sıcak noktaları",
  "Ranked by absolute chargeable emissions across every declaration in scope — the same mill appearing on four filings counts once, as one relationship.": "Kapsamdaki tüm beyanlar genelinde mutlak ücretlendirilebilir emisyonlara göre sıralanmıştır — dört dosyada görünen aynı fabrika, tek bir ilişki olarak bir kez sayılır.",
  "by supplier": "tedarikçiye göre",
