  "{count} of {total} suppliers": "{total} tedarikçiden {count}",
  "carry {pct}% of your chargeable emissions — about {amount} in certificates. That's the shortlist for a conversation about actual data, a cleaner route, or a different supplier.": "ücretlendirilebilir emisyonlarınızın %{pct} kadarını taşıyor — sertifikalarda yaklaşık {amount}. Gerçek veri, daha temiz bir rota veya farklı bir tedarikçi hakkında konuşmak için kısa liste budur.",
  "Data that needs refreshing": "Yenilenmesi gereken veriler",
  "Supplier records age. A figure past a year, or one reported for a period you're no longer filing, has to be re-confirmed before it goes into another declaration.": "Tedarikçi kayıtları eskir. Bir yılı geçmiş bir rakam ya da artık dosyalamadığınız bir dönem için raporlanmış bir rakam, başka bir beyana girmeden önce yeniden onaylanmalıdır.",
  "No supplier records yet — they build up as suppliers submit, and each one makes the next request shorter.": "Henüz tedarikçi kaydı yok — tedarikçiler gönderdikçe birikir ve her biri bir sonraki talebi kısaltır.",
  "Your one supplier record is current.": "Tek tedarikçi kaydınız güncel.",
