  "{datasets} submitted supplier datasets across {declarations} declarations, costed with the same engine the declaration workspace uses — the Annex II direct-only rule for steel and aluminium, default-value markups where a supplier reported on defaults, and any carbon price already paid deducted. Nothing here is a filed figure.": "{declarations} beyan genelinde gönderilmiş {datasets} tedarikçi veri seti; beyan çalışma alanının kullandığı aynı motorla maliyetlendirildi — çelik ve alüminyum için yalnızca doğrudan Ek II kuralı, bir tedarikçi varsayılanlar üzerinden raporladığında varsayılan değer artışları ve zaten ödenmiş karbon fiyatlarının düşülmesi. Burada dosyalanmış bir rakam yoktur.",
