  "Go to {step}": "{step} adımına git",
  "Every supplier submission must be approved before the report can be generated — the package only ever contains verified data.": "Rapor oluşturulabilmesi için her tedarikçi gönderimi onaylanmalıdır — paket yalnızca doğrulanmış veri içerir.",
  "Generate the report first — sign-off is a confirmation of the exact package that will be sent.": "Önce raporu oluşturun — onay, gönderilecek paketin birebir teyididir.",
  "Internal sign-off must be complete before anything is dispatched — every requested confirmation has to land first.": "Hiçbir şey gönderilmeden önce dahili onay tamamlanmalıdır — istenen her onayın önce gelmesi gerekir.",
  "Awaiting review": "İnceleme bekleniyor",
  "Changes requested": "Değişiklik istendi",
  "Approved": "Onaylandı",
  "Supplier submissions": "Tedarikçi gönderimleri",
  "Each supplier filled their own Smart Link, the AI checked it, they e-signed and submitted. Open a submission to read the data, loop in your internal reviewers, then approve it or request a revision.": "Her tedarikçi kendi Akıllı Bağlantısını doldurdu, YZ kontrol etti, elektronik olarak imzaladı ve gönderdi. Veriyi okumak, dahili incelemecilerinizi dahil etmek ve ardından onaylamak ya da bir düzeltme istemek için bir gönderimi açın.",
  "{count} of these products are produced by you — no link goes out for them; fill them in here and they run through the same checks.": "Bu ürünlerin {count} tanesi sizin tarafınızdan üretiliyor — bunlar için bağlantı gönderilmez; burada doldurun, aynı kontrollerden geçerler.",
  "Reminder sent": "Hatırlatma gönderildi",
  "{name} nudged by email to complete their Smart Link.": "{name} kişisine Akıllı Bağlantısını tamamlaması için e-postayla hatırlatma yapıldı.",
  "from record": "kayıttan",
  "Pulled from this company's own supplier record — they answered these goods on another declaration": "Bu şirketin kendi tedarikçi kaydından çekildi — bu malları başka bir beyanda yanıtladılar",
  "score": "puan",
