  "our own installation": "kendi tesisimiz",
  "CBAM-critical: this supplier carries a major share of the declaration's embedded emissions — the package can't be filed without them.": "CBAM açısından kritik: bu tedarikçi beyanın gömülü emisyonlarının önemli bir payını taşıyor — paket bunlar olmadan dosyalanamaz.",
  "Your organisation": "Kuruluşunuz",
  "A few details so we can set up your workspace and CBAM template correctly.": "Çalışma alanınızı ve CBAM şablonunuzu doğru kurabilmemiz için birkaç ayrıntı.",
