  "So our CBAM specialists can reach you on LINE.": "CBAM uzmanlarımızın sizinle LINE üzerinden iletişime geçebilmesi için.",
  "Enter a real telephone number — digits only, 6 to 14 of them.": "Gerçek bir telefon numarası girin — yalnızca rakam, 6 ila 14 hane.",
  "Every question on this step is required.": "Bu adımdaki her soru zorunludur.",
