  "everything we need.": "ihtiyacımız olan her şey var.",
  "We're preparing your free trial now and will email you the moment it's ready. If nothing has arrived, check your spam or junk folder.": "Ücretsiz denemenizi şimdi hazırlıyoruz ve hazır olduğu anda size e-posta göndereceğiz. Hiçbir şey gelmediyse gereksiz e-posta klasörünü kontrol edin.",
  "Add Certrace on LINE OFFICIAL": "Certrace'i LINE OFFICIAL'a ekleyin",
  "Get news and offers, and ask our CBAM specialists anything — this is the fastest way to reach us.": "Haberleri ve teklifleri alın ve CBAM uzmanlarımıza her şeyi sorun — bize ulaşmanın en hızlı yolu budur.",
  "Follow Certrace": "Certrace'i takip edin",
  "We'll email you at": "Şu adrese e-posta göndereceğiz:",
  "when your account is approved.": "hesabınız onaylandığında.",
  "Welcome": "Hoş geldiniz",
