  "Mass in tonnes": "Ton cinsinden kütle",
  "C fraction": "C kesri",
  "Carbon content": "Karbon içeriği",
  "· enter your output in Production to get the per-tonne figure": "· ton başına rakamı almak için Üretim bölümüne çıktınızı girin",
  "Your carbon data": "Karbon verileriniz",
  "Take me to the field": "Beni alana götür",
  "They’re outlined below with a note on what to check. Fix them and re-run the check before you sign.": "Aşağıda kontrol edilecek noktaya dair bir notla çerçevelenmişler. Düzeltin ve imzalamadan önce kontrolü yeniden çalıştırın.",
  "Jump to first flagged field": "İlk işaretli alana atla",
  "Back to overview": "Genel bakışa dön",
  "Continue to documents": "Belgelere devam et",
  "Certrace Supplier Portal": "Certrace Tedarikçi Portalı",
  "What you’ll be asked for": "Sizden istenecekler",
  "Supporting documents": "Destekleyici belgeler",
  "Company & installation profile": "Şirket ve tesis profili",
  "Optional, and reusable. We save this securely so your installation identity pre-fills the questionnaire now and skips re-typing on every future request from any buyer.": "İsteğe bağlı ve yeniden kullanılabilir. Bunu güvenle kaydederiz; böylece tesis kimliğiniz şimdi anketi önceden doldurur ve herhangi bir alıcıdan gelecek her talepte yeniden yazmanızı önler.",
  "Legal company name": "Yasal şirket adı",
