  "Main production route": "Ana üretim rotası",
  "e.g. EAF, BF-BOF, DRI-EAF.": "ör. EAF, BF-BOF, DRI-EAF.",
  "EAF (electric arc furnace)": "EAF (elektrik ark ocağı)",
