  "View the receipt and verification trail.": "Makbuzu ve doğrulama izini görüntüleyin.",
  "View submission": "Gönderimi görüntüle",
  "Attach your certificates": "Sertifikalarınızı ekleyin",
  "Take me to the document": "Beni belgeye götür",
  "Continue to team": "Ekibe devam et",
  "Data sharing": "Veri paylaşımı",
  "Who sees what.": "Kim neyi görür.",
  "Rows marked": "İşaretlenen satırlar",
  "Section": "Bölüm",
  "Buyers": "Alıcılar",
  "Re-using your data": "Verilerinizi yeniden kullanma",
  "Allow this exporter to reuse my saved data": "Bu ihracatçının kayıtlı verilerimi yeniden kullanmasına izin ver",
  "Team & departments": "Ekip ve birimler",
  "Split the work by department": "İşi birimlere göre bölün",
