  "Department": "Birim",
  "Remove colleague": "Meslektaşı kaldır",
  "Assigned sections": "Atanan bölümler",
  "Run quality check": "Kalite kontrolü çalıştır",
  "Finish the required fields first": "Önce zorunlu alanları tamamlayın",
  "left.": "kaldı.",
  "Take me to the first one": "Beni ilkine götür",
  "Back to questionnaire": "Anketa dön",
  "AI checks your data before you sign": "İmzalamadan önce YZ verilerinizi kontrol eder",
  "data quality score": "veri kalitesi puanı",
  "Continue to sign & submit": "İmzala ve gönder adımına devam et",
