  "Nothing here is transmitted automatically — this browser only, until you submit.": "Buradaki hiçbir şey otomatik olarak iletilmez — gönderene kadar yalnızca bu tarayıcıda kalır.",
  "Saved as you go — you can close this page and come back to it from any device.": "Girdikçe kaydedilir — bu sayfayı kapatıp herhangi bir cihazdan geri dönebilirsiniz.",
