  "The cross-sectoral correction factor is taken as 1: the Commission has not published it in the rules this was built from.": "Sektörler arası düzeltme faktörü 1 olarak alınır: Komisyon, bunun dayandığı kurallarda bunu yayımlamamıştır.",
  "A bought-in precursor's own free allocation is not netted off, so a complex good's cost is never shown lower than it is.": "Satın alınan bir öncülün kendi ücretsiz tahsisi düşülmez; bu nedenle karmaşık bir malın maliyeti asla olduğundan düşük gösterilmez.",
