  "A carbon price paid at home is recorded for {n} product(s). It is shown as claimed and never subtracted.": "{n} ürün için yurt içinde ödenen karbon fiyatı kaydedilmiştir. İddia edildiği gibi gösterilir ve asla düşülmez.",
