  "First-year verification includes a site visit, so line up your verifier early and keep the months coming in.": "İlk yıl doğrulaması bir saha ziyareti içerir, bu nedenle doğrulayıcınızı erken ayarlayın ve ayların girilmeye devam etmesini sağlayın.",
  "The dashboard shows how far each report has got, and which ones are holding the package up.": "Gösterge paneli her raporun ne kadar ilerlediğini ve paketi hangilerinin geciktirdiğini gösterir.",
  "Your free trial has ended": "Ücretsiz denemeniz sona erdi",
  "Everything you built is still here and still readable, but nothing can be changed, sent or downloaded until you choose a plan.": "Oluşturduğunuz her şey hâlâ burada ve okunabilir durumda, ancak bir plan seçene kadar hiçbir şey değiştirilemez, gönderilemez veya indirilemez.",
  "Suppliers keep their links and are never charged.": "Tedarikçiler bağlantılarını korur ve asla ücretlendirilmez.",
