  "When the trial ends the account becomes read-only: you can still open everything, but nothing can be changed, sent or downloaded.": "Deneme sona erdiğinde hesap salt okunur olur: her şeyi hâlâ açabilirsiniz, ancak hiçbir şey değiştirilemez, gönderilemez veya indirilemez.",
  "Choose a plan before then to keep working without a break.": "Aralıksız çalışmaya devam etmek için bundan önce bir plan seçin.",
