  "If that was you, there is nothing to do. If it was not, change your password now and sign out the other sessions.": "Bu sizseniz yapılacak bir şey yok. Değilse, hemen şifrenizi değiştirin ve diğer oturumları kapatın.",
  "Your password was changed": "Şifreniz değiştirildi",
