  "If you did not do this, change it again now and sign out the other sessions.": "Bunu siz yapmadıysanız, hemen tekrar değiştirin ve diğer oturumları kapatın.",
  "Your other sessions were signed out": "Diğer oturumlarınızdan çıkış yapıldı",
