  "Only this one is signed in now.": "Şu anda yalnızca bu oturum açık.",
  "Open security settings": "Güvenlik ayarlarını aç",
  "Ask Cera about this": "Bunu Cera'ya sor",
  "Certrace now speaks 中文 and हिन्दी": "Certrace artık 中文 ve हिन्दी dillerini konuşuyor",
  "The whole portal, the smart links your suppliers open, and Cera now work in English, ไทย, 中文 and हिन्दी.": "Tüm portal, tedarikçilerinizin açtığı akıllı bağlantılar ve Cera artık İngilizce, ไทย, 中文 ve हिन्दी dillerinde çalışır.",
  "Change the language from the menu under your name. Cera answers in the language you write to her in.": "Dili adınızın altındaki menüden değiştirin. Cera, kendisine yazdığınız dilde yanıt verir.",
  "Carbon & Cost and Supply Chain were redesigned": "Karbon ve Maliyet ile Tedarik Zinciri yeniden tasarlandı",
  "Carbon & Cost now compares your sites, years and products in baht, euro, yuan or rupee, with the cost on your own figures set against the EU default.": "Karbon ve Maliyet artık tesislerinizi, yıllarınızı ve ürünlerinizi baht, euro, yuan veya rupi cinsinden karşılaştırır; kendi rakamlarınızla maliyet AB varsayılanına karşı gösterilir.",
  "Supply Chain scores every supplier and precursor on how reliably the data arrives, and says where it worries us.": "Tedarik Zinciri her tedarikçiyi ve öncülü verinin ne kadar güvenilir geldiğine göre puanlar ve nerede endişe verdiğimizi belirtir.",
  "Notifications — {n} unread": "Bildirimler — {n} okunmamış",
