  "From Certrace": "Certrace'ten",
  "This is the rules as Certrace has them, not a live feed. Check the official text before you rely on it.": "Bu, Certrace'in sahip olduğu kurallardır, canlı bir akış değildir. Dayanmadan önce resmi metni kontrol edin.",
  "Open Coverage": "Kapsamı aç",
  "Unread": "Okunmamış",
  "Account": "Hesap",
  "What needs you, what has just happened, and what Certrace has to tell you — drawn from the same figures as the dashboard.": "Sizden neyin istendiği, az önce neyin olduğu ve Certrace'in size ne söylemesi gerektiği — gösterge paneliyle aynı rakamlardan alınmıştır.",
  "Sample notifications.": "Örnek bildirimler.",
  "These come from the made-up estate on the dashboard. Your own data is not touched.": "Bunlar gösterge panelindeki uydurma varlıktan gelir. Kendi verileriniz etkilenmez.",
  "Needs action": "Eylem gerekiyor",
  "Happened": "Olanlar",
  "Messages": "Mesajlar",
  "A notice appears when a month runs late, a supplier answers, a package is ready, or Certrace has something to say.": "Bir ay gecikince, bir tedarikçi yanıt verince, bir paket hazır olunca veya Certrace'in söyleyecek bir şeyi olunca bir bildirim görünür.",
  "CBAM news": "CBAM haberleri",
  "Rule changes, new certificate prices and the dates that matter — as Certrace has them.": "Kural değişiklikleri, yeni sertifika fiyatları ve önemli tarihler — Certrace'in sahip olduğu biçimiyle.",
  "Your trial, the limits of your plan and anything that needs your attention on it.": "Denemeniz, planınızın sınırları ve dikkatinizi gerektiren her şey.",
  "Thailand's excise on oil products, which carries a carbon component of THB 200/tCO₂e — Excise Department notice in the Government Gazette of 22 April 2025, unchanged at 26 October 2026": "Tayland'ın petrol ürünleri üzerindeki akaryakıt vergisi, 200 THB/tCO₂e karbon bileşeni taşır — Tüketim Vergisi Dairesi'nin 22 Nisan 2025 tarihli Resmî Gazete ilanı, 26 Ekim 2026 itibarıyla değişmedi",
  "Monthly schedule": "Aylık takvim",
