  "Boundary and processes": "Sınır ve prosesler",
  "The boundary description, the processes inside it and what is left out, with the ground for each.": "Sınır tanımı, içindeki prosesler ve dışarıda bırakılanlar, her biri için gerekçesiyle birlikte.",
  "Fuels and electricity": "Yakıtlar ve elektrik",
  "The fuels burned, the electricity supply and the meter it is read from.": "Yakılan yakıtlar, elektrik beslemesi ve okunduğu sayaç.",
  "Measuring instruments": "Ölçüm cihazları",
  "The instrument and the reading frequency for each fuel and for electricity.": "Her yakıt ve elektrik için cihaz ve okuma sıklığı.",
  "The estimates standing in for missing readings. They describe last year, so they start new unless you choose otherwise.": "Eksik okumalar yerine geçen tahminler. Geçen yılı tanımlarlar, bu nedenle aksini seçmediğiniz sürece yeniden başlarlar.",
  "Who reviews the data, and how often.": "Verileri kimin inceleyeceği ve ne sıklıkta.",
  "The drawing of the installation and what it shows.": "Tesisin çizimi ve neyi gösterdiği.",
  "Steel: the reducing agent and the mill. Aluminium: the way perfluorocarbons are counted.": "Çelik: indirgen madde ve fabrika. Alüminyum: perflorokarbonların nasıl sayıldığı.",
  "Sampling plan": "Numune alma planı",
  "How the calculation factors are determined.": "Hesaplama faktörlerinin nasıl belirlendiği.",
  "Control system": "Kontrol sistemi",
  "The controls that keep the data right.": "Verileri doğru tutan kontroller.",
  "Who supplies what, in the same tree: names, countries, CN codes, routes and contacts. Not their figures, reports or links — those are asked again.": "Aynı ağaçta kimin neyi tedarik ettiği: adlar, ülkeler, CN kodları, rotalar ve iletişim bilgileri. Rakamları, raporları veya bağlantıları değil — bunlar yeniden sorulur.",
  "The instrument, the amount per tonne, the law it is charged under and who certifies it. The receipt and any rebate are left behind.": "Cihaz, ton başına miktar, uyarınca ücretlendirildiği kanun ve onu kimin onayladığı. Makbuz ve varsa iade geride bırakılır.",
  "Who makes it": "Kim üretiyor",
  "The supplier, or your own site.": "Tedarikçi veya kendi tesisiniz.",
  "Monthly figures": "Aylık rakamlar",
