  "Sign-offs and finished versions": "Onaylar ve tamamlanmış sürümler",
  "The approvals and the stamped monitoring plans of the year behind it.": "Arkasındaki yılın onayları ve mühürlü izleme planları.",
  "Worked out again from the new year's figures.": "Yeni yılın rakamlarından yeniden hesaplanır.",
