  "Bring across": "Aktar",
  "Start new": "Yeniden başla",
  "This is a different site, so the parts that describe the old plant start new. Switch any back on if they fit.": "Bu farklı bir tesis, bu nedenle eski tesisi anlatan bölümler yeniden başlar. Uyuyorlarsa herhangi birini tekrar açın.",
  "Always comes across": "Her zaman aktarılır",
  "Always starts new": "Her zaman yeniden başlar",
  "They belong to the year they describe, so a copy never brings them.": "Tanımladıkları yıla aittirler, bu nedenle bir kopya onları asla getirmez.",
  "{n} of {total} parts come across. The rest start new.": "{total} bölümden {n} tanesi aktarılır. Geri kalanlar yeniden başlar.",
  "Nothing comes across — everything starts new.": "Hiçbir şey aktarılmaz — her şey yeniden başlar.",
