  "{n} months past the deadline and still unanswered": "{n} ay son tarihi geçti ve hâlâ yanıtlanmadı",
  "1 month ready to send: nobody has been asked yet": "1 ay göndermeye hazır: henüz kimseye sorulmadı",
  "{n} months ready to send: nobody has been asked yet": "{n} ay göndermeye hazır: henüz kimseye sorulmadı",
  "1 product has no EU volume entered, so all the tonnes made are assumed shipped to the EU.": "1 üründe AB hacmi girilmediği için üretilen tüm tonların AB'ye sevk edildiği varsayılır.",
  "{n} products have no EU volume entered, so all the tonnes made are assumed shipped to the EU.": "{n} üründe AB hacmi girilmediği için üretilen tüm tonların AB'ye sevk edildiği varsayılır.",
  "A carbon price paid at home is recorded for 1 product. It is shown as claimed and never subtracted.": "Yurt içinde ödenen bir karbon fiyatı 1 ürün için kaydedilmiştir. İddia edildiği gibi gösterilir ve asla düşülmez.",
  "A carbon price paid at home is recorded for {n} products. It is shown as claimed and never subtracted.": "Yurt içinde ödenen bir karbon fiyatı {n} ürün için kaydedilmiştir. İddia edildiği gibi gösterilir ve asla düşülmez.",
  "Add the price of 1 energy item to see this.": "Bunu görmek için 1 enerji kaleminin fiyatını ekleyin.",
  "Add the price of {n} energy items to see this.": "Bunu görmek için {n} enerji kaleminin fiyatını ekleyin.",
  "1 item of the installation's information is still missing": "Tesisin bilgilerinden 1 madde hâlâ eksik",
  "{n} items of the installation's information are still missing": "Tesisin bilgilerinden {n} madde hâlâ eksik",
  "1 item to do": "Yapılacak 1 madde",
  "{n} items to do": "Yapılacak {n} madde",
  "1 month is not submitted, so the annual figure is **incomplete, not smaller**. Every per-tonne figure above divides by a denominator that is missing that month, which overstates them.": "1 ay gönderilmedi, bu nedenle yıllık rakam **eksik, daha küçük değil**. Yukarıdaki her ton başına rakam, o ayı eksik olan bir paydaya bölünür ve bunları olduğundan büyük gösterir.",
  "{n} months are not submitted, so the annual figure is **incomplete, not smaller**. Every per-tonne figure above divides by a denominator that is missing those months, which overstates them.": "{n} ay gönderilmedi, bu nedenle yıllık rakam **eksik, daha küçük değil**. Yukarıdaki her ton başına rakam, o ayları eksik olan bir paydaya bölünür ve bunları olduğundan büyük gösterir.",
  "{fuel} fuel + {process} process": "{fuel} yakıt + {process} proses",
  "{n} months are overdue": "{n} ayın süresi geçti",
  "{product} · the oldest is {month}, {days} days late": "{product} · en eskisi {month}, {days} gün gecikmeli",
  "Plans sized to your filing.": "Beyanınızın boyutuna göre planlar.",
  "Annual term. A plan counts your own side — companies, installations, CN codes, precursors and seats. Suppliers and precursor suppliers enter and fill in through their smart link on every plan, without limit.": "Yıllık süre. Bir plan kendi tarafınızı sayar — şirketler, tesisler, CN kodları, öncüller ve koltuklar. Tedarikçiler ve öncül tedarikçiler her planda akıllı bağlantıları üzerinden sınırsız olarak girer ve doldurur.",
  "smart links unlimited": "akıllı bağlantılar sınırsız",
  "{n} pages": "{n} sayfa",
  "{n} questions": "{n} soru",
  "What the plan covers": "Planın kapsadıkları",
  "What you can use": "Kullanabilecekleriniz",
  "Installation & report package": "Tesis ve rapor paketi",
  "Provided + 1 meeting session": "Sağlanır + 1 toplantı oturumu",
  "1 business day": "1 iş günü",
  "Smart link": "Akıllı bağlantı",
  "Smart upload counts pages: an Excel file is 1 page, and every image inside it counts as one more page.": "Akıllı yükleme sayfaları sayar: bir Excel dosyası 1 sayfadır ve içindeki her görsel bir sayfa daha sayılır.",
  "Suppliers and precursor suppliers enter and fill in through their smart link on every plan — no cap, no account, no seat.": "Tedarikçiler ve öncül tedarikçiler her planda akıllı bağlantıları üzerinden girer ve doldurur — sınır yok, hesap yok, koltuk yok.",
  "One company": "Tek şirket",
  "Widest": "En geniş",
  "One company, one installation, one CN code.": "Bir şirket, bir tesis, bir CN kodu.",
  "Two installations and three CN codes, with a chain behind them.": "İki tesis ve üç CN kodu, arkasında bir zincirle.",
  "Three installations and six CN codes, with the most room to work.": "Üç tesis ve altı CN kodu, en fazla çalışma alanıyla.",
  "Your {plan} plan covers a single installation, and it is registered.": "{plan} planınız tek bir tesisi kapsar ve bu tesis kayıtlıdır.",
  "Your {plan} plan covers {cap} installations, and all of them are registered.": "{plan} planınız {cap} tesisi kapsar ve bunların tamamı kayıtlıdır.",
  "Talk to sales to raise it — suppliers and precursor suppliers can still fill in through their link, without limit.": "Artırmak için satış ekibiyle konuşun — tedarikçiler ve öncül tedarikçiler yine de bağlantıları üzerinden sınırsız olarak doldurabilir.",
  "Seats used. Suppliers fill in through their link without limit.": "Kullanılan koltuklar. Tedarikçiler bağlantıları üzerinden sınırsız olarak doldurur.",
  "Your team and what each person can do. Suppliers never take a seat — they fill in through a link, without an account.": "Ekibiniz ve her kişinin yapabildikleri. Tedarikçiler asla koltuk almaz — hesap olmadan bir bağlantı üzerinden doldururlar.",
  "Every seat on your plan is taken. Remove someone to release a seat, or talk to sales — suppliers never take a seat.": "Planınızdaki her koltuk dolu. Bir koltuğu boşaltmak için birini çıkarın veya satış ekibiyle konuşun — tedarikçiler asla koltuk almaz.",
  "Suppliers and precursor suppliers fill in through their link without limit on every plan, at any chain depth, and never take a seat.": "Tedarikçiler ve öncül tedarikçiler her planda, zincir derinliği ne olursa olsun, bağlantıları üzerinden sınırsız olarak doldurur ve asla koltuk almaz.",
